"""August vs September starts under identical 180-degree, 12–20 knot rules."""
import json
from statistics import median
from simulate_wind import ROOT,DATA


def main():
    data=json.loads((DATA/'adaptive-results-august-180-12-20kn.json').read_text());runs=data['runs']
    plan=json.loads((ROOT/'data/phase1/route-plan.json').read_text())
    labels={'ccw':'Gegen Uhrzeigersinn','cw':'Im Uhrzeigersinn'}
    finished=sum(r['completed'] for r in runs)
    lines=['# Ab August: 12–20 kn und 180°-Windfenster','','Stand: 19.10.2026. Historische Daten August–Oktober 2022–2025. Start ab jedem Tag vom 1. August bis 30. September, Reiseende spätestens 31. Oktober.','','**Windfenster:** wieder ausschliesslich Wind von der Seite oder hinten. Der kleinste Winkel zur Wind-von-Richtung beträgt 90–180° relativ zum jeweiligen Fahrkurs. Dies entspricht einem zulässigen Halbkreis von 180° und ist das ursprüngliche Seiten-/Rückenwind-Kriterium. Windstärke weiterhin **12–20 kn**.','','## Ergebnis','',f'**{finished} von {len(runs)} Läufen erreichen die vollständige Runde.** Die Tabelle trennt August- und Septemberstarts bei identischen Windregeln. Gegenüber dem vorherigen Versuch ändern sich sowohl der Startzeitraum als auch der Richtungsfilter; der direkte Vergleich mit dem alten 360°-Ergebnis würde diese beiden Effekte vermischen.','','| Startmonat | Tageslimit | Richtung | Starts mit Fahrt | Vollständige Runden | Fortschritt min. / Median / max. |','|---|---|---|---:|---:|---:|']
    for month,name in [('08','August'),('09','September')]:
        for cap in [50,75,125]:
            for direction,label in labels.items():
                rows=[r for r in runs if r['start'][5:7]==month and r['daily_cap_km']==cap and r['direction']==direction];km=[r['completed_km'] for r in rows]
                lines.append(f"| {name} | {cap} km | {label} | {sum(r['riding_days']>0 for r in rows)}/{len(rows)} | {sum(r['completed'] for r in rows)}/{len(rows)} | {min(km):.1f} / {median(km):.1f} / {max(km):.1f} km |")
    lines+=['','1.464 Läufe insgesamt: vier Jahre × 61 Starttermine × zwei Richtungen × drei Tageslimits. Pro Richtung und Limit 124 Auguststarts und 120 Septemberstarts. Die überlappenden Starttermine sind keine unabhängigen Wetterereignisse. Die Distanzen bezeichnen den erreichten Fortschritt entlang der rund 890,8 km langen Route, keine Tagesdurchschnitte.','','## Auguststarts nach Wetterjahr, maximal fünf Fahrstunden','','| Jahr | Richtung | Vollständige Runden | Fortschritt min. / Median / max. | Weitester Hotelort |','|---|---|---:|---:|---|']
    for year in [2022,2023,2024,2025]:
        for direction,label in labels.items():
            rows=[r for r in runs if r['year']==year and r['start'][5:7]=='08' and r['daily_cap_km']==125 and r['direction']==direction];km=[r['completed_km'] for r in rows];best=max(rows,key=lambda r:r['completed_km'])
            lines.append(f"| {year} | {label} | {sum(r['completed'] for r in rows)}/31 | {min(km):.1f} / {median(km):.1f} / {max(km):.1f} km | {plan['spots'][best['last_hotel']]['name']} |")
    lines+=['','## Nutzen des früheren Starts','','In diesem Lauf erreichen August- und Septemberstarts bei gleichen Windregeln dieselben Endpunkte: gegen den Uhrzeigersinn Geremeas (18,9 km); im Uhrzeigersinn nur im Wetterjahr 2025 Nora (27,5 km), sonst bleibt die Gruppe in Poetto. Die Tageslimits 50, 75 und 125 km verändern das Ergebnis nicht. Der zusätzliche August überwindet die frühen Engpässe somit nicht.','','Dies bedeutet nicht, dass im August grundsätzlich zu wenig Wind herrscht. Auf der vollständigen nächsten Teilstrecke müssen Windstärke und Windwinkel gleichzeitig zur jeweiligen Passagezeit passen. Das strenge Seiten-/Rückenwind-Kriterium bezieht sich auf jedes Stück der vorhandenen geometrischen Kurslinie.']
    if finished:
        lines+=['','## Vollständige Runden','','| Start | Richtung | Tageslimit | Ankunft | Fahrtage | Wartetage |','|---|---|---:|---|---:|---:|']
        for r in runs:
            if r['completed']:lines.append(f"| {r['start']} | {labels[r['direction']]} | {r['daily_cap_km']} km | {r['travel'][-1]['date']} | {r['riding_days']} | {r['waiting_days']} |")
    lines+=['','## Weiteste Augustverläufe bei maximal fünf Fahrstunden','','Je Richtung ein Verlauf mit dem weitesten erreichten Fortschritt, bei Gleichstand der erste Starttermin in der Ergebnisliste. Alle Fahrtage enden an einem Hotelort. Zwischen den Fahrtagen wird dort gewartet.']
    for direction,label in labels.items():
        best=max((r for r in runs if r['start'][5:7]=='08' and r['daily_cap_km']==125 and r['direction']==direction),key=lambda r:r['completed_km'])
        lines+=['',f"### {label}, Start {best['start']}",'',f"{best['completed_km']:.1f} km, {best['riding_days']} Fahrtage und {best['waiting_days']} ganze Wartetage bis zum Abschluss oder zum Ende des Betrachtungszeitraums.",'','| Datum | Von | Nach (Hotelort) | Distanz | Zusätzliche Wartezeit unterwegs¹ |','|---|---|---|---:|---:|']
        for t in best['travel']:
            lines.append(f"| {t['date']} | {plan['spots'][t['from']]['name']} | {plan['spots'][t['to']]['name']} | {t['km']:.1f} km | {sum(l['land_minutes'] for l in t['legs'][1:]):.0f} min |")
    lines+=['','¹ Zusätzlich zur Mindestpause von 25 Minuten je Zwischenlandeplatz, ohne Warten vor der ersten Tagesabfahrt.','','## Unveränderte Modellregeln','','- 25 km/h konstante Fahrtgeschwindigkeit; maximal fünf Fahrstunden. Tageslimits 50/75/125 km entsprechen höchstens zwei/drei/fünf Fahrstunden.', '- Tagesfenster 09–17 Uhr Ortszeit, Abfahrtsraster fünf Minuten, Windprüfung während der gesamten jeweiligen Teilstrecke. Ganze Wind-Wartetage und zusätzliche Landpausen sind möglich.', '- Bestehende Route ab Poetto, Sant’Antioco aussen; 21 Hotelorte. Tagesziel muss ein Hotelort sein. Hotelöffnungen und Verfügbarkeit bleiben unberücksichtigt.', '- Kein Kreuzen, keine alternativen Kurslinien oder zusätzlichen Zwischenlandeplätze. Keine separate Böengrenze. Die konstante Geschwindigkeit bei 12 kn bleibt eine Vereinfachung.', '- Der Planer kennt den historischen Wetterverlauf im Voraus und behält alle erreichbaren Hotelalternativen bei. Bei nicht abgeschlossenen Reisen zählt der weiteste Fortschritt bis 31. Oktober.', '', 'Ein fehlender Abschluss ist kein Beweis, dass die reale Reise unmöglich ist. Rasterwind, feste Teilstrecken und das recherchierte Hotelnetz begrenzen die Aussage. Insbesondere kann ein 50-km-Tageslimit grössere Lücken zwischen Hotelorten nicht überbrücken.','','## Augustdaten, Quellen und Reproduktion','']
    coverage=json.loads((DATA/'coverage-august.json').read_text())
    lines += [f"Ergänzt wurden {coverage['request_points']} Abfragepunkte × 31 Augusttage × 24 Stunden × vier Jahre = **{coverage['point_hours']:,} Punktstunden**; fehlende Werte: **{coverage['total_nulls']}**. Zusammen mit September/Oktober umfasst die Simulation 92 Tage je Jahr. August und September werden an der UTC-Stundengrenze lückenlos verbunden; lokale Fahrzeiten berücksichtigen Europe/Rome.", '', 'Quelle: [Open-Meteo Historical Weather API](https://open-meteo.com/en/docs/historical-weather-api), ECMWF IFS, Windgeschwindigkeit und Windrichtung in 10 m Höhe, Böen zusätzlich archiviert. Nominell rund 9 km Raster; lokale Strandwinde nur eingeschränkt erfasst. Modell, Abfragepunkte und Parameter entsprechen dem [bisherigen Datensatz](11-wind-api-und-daten.md). Hotelquellen: [Hotelnetz und Wartepausen](13-variable-etappen-wartepausen.md).','','Die neuen API-Abfragen verwenden pro Jahr `start_date=YYYY-08-01` und `end_date=YYYY-08-31`, `models=ecmwf_ifs`, `cell_selection=sea`, `elevation=nan`, `wind_speed_unit=kn`, `timezone=GMT` und `timeformat=unixtime`. Je fünf Koordinaten pro Anfrage. Rohantworten, vollständige URLs, Abrufzeitpunkte und SHA-256-Prüfsummen liegen in [raw-august](../data/phase2/raw-august/). Die September-/Oktoberdateien werden unverändert weiterverwendet.','','```sh','python3 scripts/fetch_wind.py --august-only','python3 scripts/validate_wind_data.py --august-only','python3 scripts/simulate_adaptive.py --august','python3 scripts/report_wind_august.py','python3 scripts/validate_adaptive_results.py adaptive-results-august-180-12-20kn.json',"python3 -m unittest discover -s scripts -p 'test_*.py'",'```','','- [August-Abdeckung](../data/phase2/coverage-august.json)', '- [Konfiguration](../data/phase2/simulation-config-august-180-12-20kn.json)', '- [Alle Reiseverläufe und Teilfahrten](../data/phase2/adaptive-results-august-180-12-20kn.json)','','Vorherige Szenarien bleiben unverändert reproduzierbar. Winddaten: ECMWF / Open-Meteo; eigene Modellrechnung.']
    (ROOT/'docs/17-ab-august-180-grad.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':main()
